vector<double> olsFit(vector<double>& x, vector<double>& y) {
    int n = x.size(); double mx = 0, my = 0; for (int i = 0; i < n; i++) { mx += x[i]; my += y[i]; } mx /= n; my /= n;
    double sxy = 0, sxx = 0; for (int i = 0; i < n; i++) { sxy += (x[i] - mx) * (y[i] - my); sxx += (x[i] - mx) * (x[i] - mx); }
    double b = sxy / sxx; return {b, my - b * mx};
}
